<script setup lang="ts">import { categories, products } from '~/data/catalog'; const route=useRoute(); const category=computed(()=>categories.find(c=>c.slug===route.params.slug)); const filtered=computed(()=>products.filter(p=>p.categoryId===category.value?.id));</script>
<template><section class="container-page py-14"><p class="mb-5 text-xs text-secondary">Главная / Каталог / {{ category?.name }}</p><h1 class="mb-12 text-5xl font-light">{{ category?.name || 'Категория' }}</h1><div v-if="filtered.length" class="grid grid-cols-2 gap-x-4 gap-y-12 lg:grid-cols-4"><ProductCard v-for="p in filtered" :key="p.id" :product="p"/></div><div v-else class="bg-surface p-12 text-center text-secondary">Товары этой категории скоро появятся.</div></section></template>
